from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

import heapq
import itertools


def _temporal(data, exact, minimum_duration):
    required = data.get("required", [])
    full = (1 << len(required)) - 1
    visit = {node: sum(1 << i for i, name in enumerate(required) if name == node)
             for node in set(required)}
    initial_mask = visit.get(data["source"], 0)
    budget = data["coupons"]
    start = data["start"]
    initial = (data["source"], initial_mask, 0)
    distances = {initial: start}
    queue = [(start, data["source"], initial_mask, 0)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        arrival, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != arrival:
            continue
        if (node == data["target"] and mask == full
                and (not exact or used == budget)):
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], used)]
            if used < budget:
                discounted = max(minimum_duration,
                                 edge["duration"] - edge.get("discount", 0))
                choices.append((discounted, used + 1))
            next_node = edge["v"]
            next_mask = mask | visit.get(next_node, 0)
            for duration, next_used in choices:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_state = (next_node, next_mask, next_used)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node,
                                           next_mask, next_used))
    return {"arrival": None}


def _route(exact, minimum_duration):
    return lambda data: _temporal(data, exact, minimum_duration)


def _ledger(data):
    def rounded(numerator, denominator):
        if data["rounding"] == "half_up":
            return (2 * numerator + denominator) // (2 * denominator)
        return numerator // denominator

    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]

    domains = {}
    rows_by_name = {}
    for name in names:
        rows = {row["version"]: row for row in packages[name]
                if row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])}
        rows_by_name[name] = rows
        domains[name] = [None] + sorted(rows)

    best_vector = None
    best_versions = None
    for values in itertools.product(*(domains[name] for name in names)):
        versions = {name: value for name, value in zip(names, values)
                    if value is not None}
        if any(name not in versions or not low <= versions[name] <= high
               for name, (low, high) in roots.items()):
            continue

        edges = {name: [] for name in versions}
        valid = True
        for name, version in versions.items():
            row = rows_by_name[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if (target not in versions
                        or not dep["min"] <= versions[target] <= dep["max"]):
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        finished, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            for target in edges[name]:
                if not visit(target):
                    return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in edges):
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges[name])
        if reachable != set(versions):
            continue

        vector = tuple(versions.get(name, -1) for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_versions = versions

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _quota_jobs(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    options = [job for job in jobs if job["id"] not in blocked]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    if k > len(options):
        return {"error": "impossible"}

    best_value = None
    best_ids = None
    for chosen in itertools.combinations(options, k):
        ids = {job["id"] for job in chosen}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        active = []
        compatible = True
        for job in sorted(chosen, key=lambda row: (row["start"], row["end"])):
            active = [end for end in active if end > job["start"]]
            active.append(job["end"])
            if len(active) > 2:
                compatible = False
                break
        if not compatible:
            continue

        value = sum(job["value"] for job in chosen)
        ordered_ids = sorted(ids)
        if (best_value is None or value > best_value
                or (value == best_value and ordered_ids < best_ids)):
            best_value = value
            best_ids = ordered_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


SOLVERS = {
    "component_01": _route(True, 2),
    "component_02": _route(False, 1),
    "component_03": _route(True, 1),
    "component_04": _route(False, 2),
    "component_05": _route(True, 2),
    "component_06": _ledger,
    "component_07": _dependencies,
    "component_08": _quota_jobs,
}
